  "variantNote": "原词条美式读音：沙漠义名词、形容词 /ˈdezərt/；动词及应得报偿义名词 /dɪˈzɝːt/。 英美音的主要区别之一是美音读出 r 音。重音还要按词义判断，不能概括成所有名词都重读前面。 “沙漠”义名词和形容词都重读第一音节，元音与 bed 中的 /e/ 相同。 动词和“应得的报偿”义名词重读第二音节，首音节为非重读 /dɪ/。 just deserts 中的 deserts 读 /dɪˈzɜːts/（英）或 /dɪˈzɝːts/（美），不是“沙漠”义的复数读音。 动词 desert 与 dessert“甜点”同音；拼写和词义仍不同。",
